begin;
alter function public.accept_society_invitation(uuid) set schema private;
alter function public.get_society_members_directory(uuid) set schema private;
alter function public.grant_society_role(uuid,uuid,text,date,date,text) set schema private;
alter function public.revoke_society_role(uuid,uuid,text,text) set schema private;
alter function public.set_society_membership_status(uuid,uuid,text,text) set schema private;
alter function public.verify_party_user_link(uuid,text,uuid,text,date,text) set schema private;
revoke all on function private.accept_society_invitation(uuid) from public,anon,authenticated;
revoke all on function private.get_society_members_directory(uuid) from public,anon,authenticated;
revoke all on function private.grant_society_role(uuid,uuid,text,date,date,text) from public,anon,authenticated;
revoke all on function private.revoke_society_role(uuid,uuid,text,text) from public,anon,authenticated;
revoke all on function private.set_society_membership_status(uuid,uuid,text,text) from public,anon,authenticated;
revoke all on function private.verify_party_user_link(uuid,text,uuid,text,date,text) from public,anon,authenticated;
grant execute on function private.accept_society_invitation(uuid) to authenticated;
grant execute on function private.get_society_members_directory(uuid) to authenticated;
grant execute on function private.grant_society_role(uuid,uuid,text,date,date,text) to authenticated;
grant execute on function private.revoke_society_role(uuid,uuid,text,text) to authenticated;
grant execute on function private.set_society_membership_status(uuid,uuid,text,text) to authenticated;
grant execute on function private.verify_party_user_link(uuid,text,uuid,text,date,text) to authenticated;
create or replace function public.accept_society_invitation(p_society_id uuid) returns boolean language sql set search_path='' as $function$ select private.accept_society_invitation(p_society_id); $function$;
create or replace function public.get_society_members_directory(p_society_id uuid) returns jsonb language sql stable set search_path='' as $function$ select private.get_society_members_directory(p_society_id); $function$;
create or replace function public.grant_society_role(p_society_id uuid,p_user_id uuid,p_role_code text,p_valid_from date default current_date,p_valid_until date default null,p_reason text default null) returns uuid language sql set search_path='' as $function$ select private.grant_society_role(p_society_id,p_user_id,p_role_code,p_valid_from,p_valid_until,p_reason); $function$;
create or replace function public.revoke_society_role(p_society_id uuid,p_user_id uuid,p_role_code text,p_reason text) returns boolean language sql set search_path='' as $function$ select private.revoke_society_role(p_society_id,p_user_id,p_role_code,p_reason); $function$;
create or replace function public.set_society_membership_status(p_society_id uuid,p_user_id uuid,p_status text,p_reason text) returns boolean language sql set search_path='' as $function$ select private.set_society_membership_status(p_society_id,p_user_id,p_status,p_reason); $function$;
create or replace function public.verify_party_user_link(p_society_id uuid,p_party_id text,p_user_id uuid,p_relationship_code text,p_valid_until date default null,p_reason text default null) returns uuid language sql set search_path='' as $function$ select private.verify_party_user_link(p_society_id,p_party_id,p_user_id,p_relationship_code,p_valid_until,p_reason); $function$;
revoke all on function public.accept_society_invitation(uuid) from public,anon;
revoke all on function public.get_society_members_directory(uuid) from public,anon;
revoke all on function public.grant_society_role(uuid,uuid,text,date,date,text) from public,anon;
revoke all on function public.revoke_society_role(uuid,uuid,text,text) from public,anon;
revoke all on function public.set_society_membership_status(uuid,uuid,text,text) from public,anon;
revoke all on function public.verify_party_user_link(uuid,text,uuid,text,date,text) from public,anon;
grant execute on function public.accept_society_invitation(uuid) to authenticated;
grant execute on function public.get_society_members_directory(uuid) to authenticated;
grant execute on function public.grant_society_role(uuid,uuid,text,date,date,text) to authenticated;
grant execute on function public.revoke_society_role(uuid,uuid,text,text) to authenticated;
grant execute on function public.set_society_membership_status(uuid,uuid,text,text) to authenticated;
grant execute on function public.verify_party_user_link(uuid,text,uuid,text,date,text) to authenticated;
commit;